let file = """{"version":3,"file":"load3dPreviewExtensions-CQOhtYc3.js","names":[],"sources":["../../src/extensions/core/load3dPreviewExtensions.ts"],"sourcesContent":["import { nextTick } from 'vue'\n\nimport { nodeToLoad3dMap, useLoad3d } from '@/composables/useLoad3d'\nimport { createExportMenuItems } from '@/extensions/core/load3d/exportMenuHelper'\nimport type {\n  CameraConfig,\n  LoadFolder,\n  Model3DInfo\n} from '@/extensions/core/load3d/interfaces'\nimport type Load3d from '@/extensions/core/load3d/Load3d'\nimport Load3DConfiguration from '@/extensions/core/load3d/Load3DConfiguration'\nimport type { Model3DOutput } from '@/extensions/core/load3d/model3dOutput'\nimport { readModel3DOutput } from '@/extensions/core/load3d/model3dOutput'\nimport { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { IContextMenuValue } from '@/lib/litegraph/src/types/contextMenu'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type { NodeExecutionOutput } from '@/platform/remote/comfyui/execution/types'\nimport { app } from '@/scripts/app'\nimport { useExtensionService } from '@/services/extensionService'\nimport { useLoad3dService } from '@/services/load3dService'\nimport type { ComfyExtension } from '@/types/comfy'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\nimport { getNodeByLocatorId } from '@/utils/graphTraversalUtil'\n\nfunction applyResultToLoad3d(\n  node: LGraphNode,\n  load3d: Load3d,\n  reported: Model3DOutput,\n  loadFolder: LoadFolder\n): void {\n  const { cameraState, modelTransform } = reported\n  const normalizedPath = reported.filePath.replaceAll('\\\\', '/')\n  const folder = reported.folder ?? loadFolder\n  node.properties['Last Time Model File'] = normalizedPath\n  node.properties['Last Time Model Folder'] = folder\n  if (cameraState) {\n    const existing = node.properties['Camera Config'] as\n      | CameraConfig\n      | undefined\n    node.properties['Camera Config'] = {\n      cameraType: load3d.getCurrentCameraType(),\n      fov: 75,\n      ...existing,\n      state: cameraState\n    }\n  }\n\n  const config = new Load3DConfiguration(load3d, node.properties)\n  config.configureForSaveMesh(folder, normalizedPath, {\n    silentOnNotFound: true\n  })\n\n  const targetGeneration = load3d.currentLoadGeneration\n  void load3d.whenLoadIdle().then(() => {\n    if (load3d.currentLoadGeneration !== targetGeneration) return\n    if (cameraState) load3d.setCameraState(cameraState)\n    if (modelTransform) load3d.applyModelTransform(modelTransform)\n    load3d.forceRender()\n  })\n}\n\nfunction createPreview3DExtension(\n  comfyClass: string,\n  extensionName: string,\n  loadFolder: LoadFolder\n): ComfyExtension {\n  const applyPreviewOutput = (\n    node: LGraphNode,\n    reported: Model3DOutput\n  ): void => {\n    useLoad3d(node).waitForLoad3d((load3d) => {\n      applyResultToLoad3d(node, load3d, reported, loadFolder)\n    })\n  }\n\n  return {\n    name: extensionName,\n\n    onNodeOutputsUpdated(\n      nodeOutputs: Record<NodeLocatorId, NodeExecutionOutput>\n    ) {\n      for (const [locatorId, output] of Object.entries(nodeOutputs)) {\n        const reported = readModel3DOutput(output)\n        if (!reported) continue\n\n        const node = getNodeByLocatorId(app.rootGraph, locatorId)\n        if (!node || node.constructor.comfyClass !== comfyClass) continue\n\n        applyPreviewOutput(node, reported)\n      }\n    },\n\n    getNodeMenuItems(node: LGraphNode): (IContextMenuValue | null)[] {\n      if (node.constructor.comfyClass !== comfyClass) return []\n\n      const load3d = useLoad3dService().getLoad3d(node)\n      if (!load3d) return []\n\n      if (load3d.isSplatModel()) return []\n\n      return createExportMenuItems(load3d)\n    },\n\n    async nodeCreated(node: LGraphNode) {\n      if (node.constructor.comfyClass !== comfyClass) return\n\n      const [oldWidth, oldHeight] = node.size\n      node.setSize([Math.max(oldWidth, 400), Math.max(oldHeight, 550)])\n\n      await nextTick()\n\n      const onExecuted = node.onExecuted\n      const { onLoad3dReady, waitForLoad3d } = useLoad3d(node)\n\n      onLoad3dReady((load3d) => {\n        const lastTimeModelFile = node.properties['Last Time Model File']\n        if (!lastTimeModelFile) return\n\n        const lastTimeModelFolder = node.properties['Last Time Model Folder']\n        const folder =\n          lastTimeModelFolder === 'temp' || lastTimeModelFolder === 'output'\n            ? lastTimeModelFolder\n            : loadFolder\n\n        const config = new Load3DConfiguration(load3d, node.properties)\n        config.configureForSaveMesh(folder, lastTimeModelFile as string, {\n          silentOnNotFound: true\n        })\n\n        const cameraConfig = node.properties['Camera Config'] as\n          | CameraConfig\n          | undefined\n        const cameraState = cameraConfig?.state\n        const targetGeneration = load3d.currentLoadGeneration\n        void load3d.whenLoadIdle().then(() => {\n          if (load3d.currentLoadGeneration !== targetGeneration) return\n          if (cameraState) load3d.setCameraState(cameraState)\n          load3d.forceRender()\n        })\n      })\n\n      waitForLoad3d((load3d) => {\n        const resolveLoad3d = () => nodeToLoad3dMap.get(node) ?? load3d\n\n        const sceneWidget = node.widgets?.find(\n          (w) => w.name === 'viewport_state'\n        )\n        const widthWidget = node.widgets?.find((w) => w.name === 'width')\n        const heightWidget = node.widgets?.find((w) => w.name === 'height')\n\n        if (widthWidget && heightWidget) {\n          load3d.setTargetSize(\n            widthWidget.value as number,\n            heightWidget.value as number\n          )\n          widthWidget.callback = (value: number) => {\n            resolveLoad3d().setTargetSize(value, heightWidget.value as number)\n          }\n          heightWidget.callback = (value: number) => {\n            resolveLoad3d().setTargetSize(widthWidget.value as number, value)\n          }\n        }\n\n        if (sceneWidget) {\n          sceneWidget.serializeValue = async () => {\n            const currentLoad3d = nodeToLoad3dMap.get(node)\n            if (!currentLoad3d) {\n              console.error('No load3d instance found for node')\n              return null\n            }\n\n            const cameraConfig: CameraConfig = (node.properties[\n              'Camera Config'\n            ] as CameraConfig | undefined) || {\n              cameraType: currentLoad3d.getCurrentCameraType(),\n              fov: currentLoad3d.cameraManager.perspectiveCamera.fov\n            }\n            const cameraState = currentLoad3d.getCameraState()\n            cameraConfig.state = cameraState\n            node.properties['Camera Config'] = cameraConfig\n\n            const modelInfo = currentLoad3d.getModelInfo()\n            const model_3d_info: Model3DInfo = modelInfo ? [modelInfo] : []\n\n            return {\n              image: '',\n              mask: '',\n              normal: '',\n              camera_info: cameraState,\n              recording: '',\n              model_3d_info\n            }\n          }\n        }\n\n        node.onExecuted = function (output: NodeExecutionOutput) {\n          onExecuted?.call(this, output)\n\n          const reported = readModel3DOutput(output)\n          if (!reported) {\n            const msg = t('toastMessages.unableToGetModelFilePath')\n            console.error(msg)\n            useToast().warning(msg)\n            return\n          }\n\n          applyResultToLoad3d(node, resolveLoad3d(), reported, loadFolder)\n        }\n      })\n    }\n  }\n}\n\nuseExtensionService().registerExtension(\n  createPreview3DExtension(\n    'PreviewGaussianSplat',\n    'Comfy.PreviewGaussianSplat',\n    'temp'\n  )\n)\nuseExtensionService().registerExtension(\n  createPreview3DExtension(\n    'PreviewPointCloud',\n    'Comfy.PreviewPointCloud',\n    'temp'\n  )\n)\nuseExtensionService().registerExtension(\n  createPreview3DExtension(\n    'SaveGaussianSplat',\n    'Comfy.SaveGaussianSplat',\n    'output'\n  )\n)\nuseExtensionService().registerExtension(\n  createPreview3DExtension('SavePointCloud', 'Comfy.SavePointCloud', 'output')\n)\n"],"mappings":"0gBAyBA,SAAS,oBACP,EACA,EACA,EACA,EACM,CACN,GAAM,CAAE,cAAa,kBAAmB,EAClC,EAAiB,EAAS,SAAS,WAAW,KAAM,GAAG,EACvD,EAAS,EAAS,QAAU,EAGlC,GAFA,EAAK,WAAW,wBAA0B,EAC1C,EAAK,WAAW,0BAA4B,EACxC,EAAa,CACf,IAAM,EAAW,EAAK,WAAW,iBAGjC,EAAK,WAAW,iBAAmB,CACjC,WAAY,EAAO,qBAAqB,EACxC,IAAK,GACL,GAAG,EACH,MAAO,CACT,CACF,CAGA,IADmB,EAAoB,EAAQ,EAAK,UACpD,CAAA,CAAO,qBAAqB,EAAQ,EAAgB,CAClD,iBAAkB,EACpB,CAAC,EAED,IAAM,EAAmB,EAAO,sBAChC,EAAY,aAAa,CAAC,CAAC,SAAW,CAChC,EAAO,wBAA0B,IACjC,GAAa,EAAO,eAAe,CAAW,EAC9C,GAAgB,EAAO,oBAAoB,CAAc,EAC7D,EAAO,YAAY,EACrB,CAAC,CACH,CAEA,SAAS,yBACP,EACA,EACA,EACgB,CAChB,IAAM,oBACJ,EACA,IACS,CACT,EAAU,CAAI,CAAC,CAAC,cAAe,GAAW,CACxC,oBAAoB,EAAM,EAAQ,EAAU,CAAU,CACxD,CAAC,CACH,EAEA,MAAO,CACL,KAAM,EAEN,qBACE,EACA,CACA,IAAK,GAAM,CAAC,EAAW,KAAW,OAAO,QAAQ,CAAW,EAAG,CAC7D,IAAM,EAAW,EAAkB,CAAM,EACzC,GAAI,CAAC,EAAU,SAEf,IAAM,EAAO,EAAmB,EAAI,UAAW,CAAS,EACpD,CAAC,GAAQ,EAAK,YAAY,aAAe,GAE7C,mBAAmB,EAAM,CAAQ,CACnC,CACF,EAEA,iBAAiB,EAAgD,CAC/D,GAAI,EAAK,YAAY,aAAe,EAAY,MAAO,CAAC,EAExD,IAAM,EAAS,EAAiB,CAAC,CAAC,UAAU,CAAI,EAKhD,MAJI,CAAC,GAED,EAAO,aAAa,EAAU,CAAC,EAE5B,EAAsB,CAAM,CACrC,EAEA,MAAM,YAAY,EAAkB,CAClC,GAAI,EAAK,YAAY,aAAe,EAAY,OAEhD,GAAM,CAAC,EAAU,GAAa,EAAK,KACnC,EAAK,QAAQ,CAAC,KAAK,IAAI,EAAU,GAAG,EAAG,KAAK,IAAI,EAAW,GAAG,CAAC,CAAC,EAEhE,MAAM,EAAS,EAEf,IAAM,EAAa,EAAK,WAClB,CAAE,gBAAe,iBAAkB,EAAU,CAAI,EAEvD,EAAe,GAAW,CACxB,IAAM,EAAoB,EAAK,WAAW,wBAC1C,GAAI,CAAC,EAAmB,OAExB,IAAM,EAAsB,EAAK,WAAW,0BACtC,EACJ,IAAwB,QAAU,IAAwB,SACtD,EACA,EAGN,IADmB,EAAoB,EAAQ,EAAK,UACpD,CAAA,CAAO,qBAAqB,EAAQ,EAA6B,CAC/D,iBAAkB,EACpB,CAAC,EAKD,IAAM,EAHe,EAAK,WAAW,gBAGjB,EAAc,MAC5B,EAAmB,EAAO,sBAChC,EAAY,aAAa,CAAC,CAAC,SAAW,CAChC,EAAO,wBAA0B,IACjC,GAAa,EAAO,eAAe,CAAW,EAClD,EAAO,YAAY,EACrB,CAAC,CACH,C